$Root = Split-Path -Parent $PSScriptRoot; $Status = Join-Path $Root 'state\latest_status.json'
while ($true) { Clear-Host; if (Test-Path $Status) { $s=Get-Content $Status -Raw|ConvertFrom-Json; $current=if($null -eq $s.current_experiment){'IDLE'}else{$s.current_experiment.id}; $pct=if($null -eq $s.available_scope_percent){0}else{$s.available_scope_percent}; Write-Progress -Activity "Whisper Research" -Status $current -PercentComplete $pct; Write-Host "[$pct% available | $($s.full_roadmap_percent)% full] $current"; Write-Host "GPU $($s.gpu.utilization_percent)% VRAM $($s.gpu.vram_used_mb)/$($s.gpu.vram_total_mb) MB"; if($s.last_error){Write-Host "Last: $($s.last_error)" -ForegroundColor Yellow}; $age=((Get-Date)-[datetime]$s.timestamp).TotalSeconds; if($age -gt 15){Write-Host "HEARTBEAT STALE: $([int]$age)s" -ForegroundColor Red} } else { Write-Host 'Waiting for status...' }; Start-Sleep -Seconds 4 }
